{  "explanation": "A line of best fit (least-squares regression) chooses slope m and intercept b to minimize the sum of squared vertical distances from each data point to the line. The formulas are m = Σ(x−x̄)(y−ȳ) / Σ(x−x̄)² and b = ȳ − m·x̄, and R² measures how much of the variance in y the line explains. Drag any of the blue points and the regression line, its equation, and R² update in real time. Toggle 'Show residuals' to see the exact vertical errors being minimized, or hit 'Randomize points' for a fresh dataset.",  "manimCode": "// ----- Axes -----
const ax = new Axes({
  xRange: [0, 10, 1],
  yRange: [0, 7, 1],
  xLength: 9,
  yLength: 5.2,
  tips: false,
});
const axLabels = ax.getAxisLabels();
scene.add(ax, axLabels);

// pixel <-> data conversion helpers
const originPt = ax.c2p(0, 0);
const xMaxPt = ax.c2p(10, 0);
const yMaxPt = ax.c2p(0, 7);
const pixX = (xMaxPt[0] - originPt[0]) / 10;
const pixY = (yMaxPt[1] - originPt[1]) / 7;
function toData(pt) {
  return [(pt[0] - originPt[0]) / pixX, (pt[1] - originPt[1]) / pixY];
}

// ----- residual segments (added first so they sit behind points) -----
const residuals = [];
for (let i = 0; i < 7; i++) {
  const r = new Polygon({ vertices: [[0, 0, 0], [0, 0.001, 0]], color: RED });
  r.setStrokeWidth(2).setFillOpacity(0);
  scene.add(r);
  residuals.push(r);
}

// ----- regression line (2-vertex polygon so vertices update live) -----
const fitLine = new Polygon({ vertices: [[0, 0, 0], [1, 0, 0]], color: GOLD });
fitLine.setStrokeWidth(4).setFillOpacity(0);
scene.add(fitLine);

// ----- draggable data points -----
const startData = [[1, 1.2], [2.2, 2.9], [3.5, 2.3], [5, 4.4], [6.4, 3.9], [8, 5.7], [9, 5.1]];
const dots = startData.map(([x, y]) => new Dot({ point: ax.c2p(x, y), radius: 0.15, color: BLUE_B }));
dots.forEach(d => scene.add(d));

// ----- state + live least-squares update -----
let eqLabel = null;
let showRes = true;

function updateFit() {
  const pts = dots.map(d => toData(d.getCenter()));
  const n = pts.length;

  // means
  let mx = 0, my = 0;
  pts.forEach(p => { mx += p[0]; my += p[1]; });
  mx /= n; my /= n;

  // least-squares slope & intercept
  let sxy = 0, sxx = 0;
  pts.forEach(p => { sxy += (p[0] - mx) * (p[1] - my); sxx += (p[0] - mx) * (p[0] - mx); });
  const m = sxx < 1e-12 ? 0 : sxy / sxx;
  const b = my - m * mx;

  // R^2
  let ssRes = 0, ssTot = 0;
  pts.forEach(p => {
    const f = m * p[0] + b;
    ssRes += (p[1] - f) * (p[1] - f);
    ssTot += (p[1] - my) * (p[1] - my);
  });
  const r2 = ssTot < 1e-12 ? 1 : Math.max(0, 1 - ssRes / ssTot);

  // clamp line endpoints to the axes box [0,10] x [0,7]
  const cand = [];
  const tryAdd = (x, y) => {
    if (x >= -1e-9 && x <= 10 + 1e-9 && y >= -1e-9 && y <= 7 + 1e-9) {
      cand.push([Math.max(0, Math.min(10, x)), Math.max(0, Math.min(7, y))]);
    }
  };
  tryAdd(0, b);
  tryAdd(10, 10 * m + b);
  if (Math.abs(m) > 1e-9) {
    tryAdd(-b / m, 0);
    tryAdd((7 - b) / m, 7);
  }
  if (cand.length < 2) {
    cand.length = 0;
    cand.push([0, Math.min(7, Math.max(0, b))], [10, Math.min(7, Math.max(0, 10 * m + b))]);
  }
  fitLine.setVertices([ax.c2p(cand[0][0], cand[0][1]), ax.c2p(cand[1][0], cand[1][1])]);

  // residual segments: point -> line (vertical distance)
  pts.forEach((p, i) => {
    residuals[i].setVertices([ax.c2p(p[0], p[1]), ax.c2p(p[0], m * p[0] + b)]);
    residuals[i].setOpacity(showRes ? 0.85 : 0);
  });

  // equation label (Text is immutable -> remove & recreate)
  const sign = b >= 0 ? '+' : '-';
  const eq = 'y = ' + m.toFixed(2) + 'x ' + sign + ' ' + Math.abs(b).toFixed(2) + '      R² = ' + r2.toFixed(3);
  if (eqLabel) scene.remove(eqLabel);
  eqLabel = new Text({ text: eq, color: GOLD, fontSize: 28 });
  eqLabel.moveTo([0, 3.2, 0]);
  scene.add(eqLabel);
}

updateFit();

// ----- interactivity: drag points, line follows -----
dots.forEach(d => {
  makeDraggable(d, scene, {
    constrainX: [originPt[0] + 0.05, xMaxPt[0] - 0.05],
    constrainY: [originPt[1] + 0.05, yMaxPt[1] - 0.05],
    onDrag: updateFit,
  });
  makeHoverable(d, scene, { hoverScale: 1.3, cursor: 'grab' });
});

// ----- title & hint -----
const title = new Text({ text: 'Least-Squares Line of Best Fit', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.7, 0]);
scene.add(title);

const hint = new Text({ text: 'Drag any point — the best-fit line updates live', color: GRAY, fontSize: 22 });
hint.moveTo([0, -3.5, 0]);
scene.add(hint);

// ----- controls -----
const controls = new Controls(scene, { position: 'top-right' });
controls.addCheckbox({
  label: 'Show residuals',
  checked: true,
  onChange: (c) => { showRes = c; updateFit(); },
});
controls.addButton({
  label: 'Randomize points',
  onClick: () => {
    dots.forEach(d => {
      const rx = 0.5 + Math.random() * 9;
      const ry = 0.5 + Math.random() * 6;
      d.moveTo(ax.c2p(rx, ry));
    });
    updateFit();
  },
});

await scene.wait(999999);"}

